<script setup lang="ts">
import { computed } from 'vue'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import { useHealthStore } from '../../stores/health'
import { navigate } from '../../utils/ui'
const store=useHealthStore()
const days=computed(()=>new Set([...store.data.meals.map(x=>x.date),...store.data.bodies.map(x=>x.date),...store.data.training.map(x=>x.date)]).size)
const items=[{page:'goals',icon:'target',title:'个人与目标',detail:'身体信息、体重与每日营养目标'},{page:'body',icon:'scale',title:'身体趋势',detail:'体重、腰围、体脂与变化'},{page:'weekly',icon:'book',title:'每周回顾',detail:'回看饮食、训练和身体变化'},{page:'favorites',icon:'star',title:'常吃食物',detail:'让每一餐记录再简单一点'}]
function localInfo(){uni.showModal({title:'关于本地记录',content:'所有记录仅保存在当前设备，不上传服务器，也不跨设备同步。浏览器和微信的数据互相独立。清理浏览器站点数据、微信缓存或卸载应用可能导致记录及照片丢失。',showCancel:false,confirmColor:'#176539'})}
</script>
<template><AppPage tab="profile"><text class="eyebrow">A BETTER RELATIONSHIP WITH YOURSELF</text><text class="page-title">我的轻衡</text><view class="profile-card"><view class="profile-avatar"><text v-if="store.data.profile.name">{{ store.data.profile.name.slice(0,1) }}</text><Icon v-else name="leaf" tone="white" :size="33"/></view><view class="grow"><text class="profile-name">{{ store.data.profile.name||'轻衡的朋友' }}</text><text class="profile-caption">好好照顾自己，从今天开始。</text><text class="pill mt-16">{{ store.data.profile.goal }}</text></view><button role="button" class="icon-button plain" aria-label="编辑个人信息" @click="navigate('goals')"><Icon name="edit" tone="muted" :size="20"/></button></view><view class="profile-stats"><view><text class="stat-number number">{{ days }}<text class="stat-unit">天</text></text><text class="stat-label">留下记录</text></view><view><text class="stat-number number">{{ store.data.training.length }}<text class="stat-unit">次</text></text><text class="stat-label">训练积累</text></view><view><text class="stat-number number">{{ store.data.favorites.length }}<text class="stat-unit">种</text></text><text class="stat-label">常吃食物</text></view></view><view class="section card list-menu"><view v-for="item in items" :key="item.page" class="menu-item" @click="navigate(item.page)"><view class="row gap-12"><view class="menu-icon"><Icon :name="item.icon" :size="20"/></view><view><text class="menu-title">{{ item.title }}</text><text class="menu-description">{{ item.detail }}</text></view></view><Icon name="arrow" tone="muted" :size="14"/></view></view><view class="local-card" @click="localInfo"><view class="row gap-12"><Icon name="shield" :size="24"/><view class="grow"><text class="local-title">你的数据，留在你的设备</text><text class="helper">免登录 · 本地保存 · 暂不支持跨设备同步</text></view><Icon name="info" tone="muted" :size="17"/></view></view><view v-if="store.storageIssue" class="error-message">{{ store.storageIssue }}</view><view class="profile-quote"><text class="quote-mark">“</text><text>不用成为别人的样子，{{ '\n' }}慢慢成为更舒服的自己。</text><view class="quote-line"/><text class="quote-en">A LITTLE BALANCE, EVERY DAY.</text></view><text class="footer-note">轻衡 v0.1.0 · 前端本地版</text></AppPage></template>
<style scoped>.profile-card{display:flex;align-items:center;gap:16px;margin-top:27px}.profile-avatar{width:64px;height:64px;border-radius:23px;background:var(--forest);display:flex;align-items:center;justify-content:center;flex-shrink:0;transform:rotate(-4deg);color:white;font-size:28px}.profile-name{display:block;font-size:19px;font-weight:600}.profile-caption{display:block;font-size:10px;color:var(--muted);margin-top:7px}.profile-card .pill{margin-top:11px!important}.profile-stats{display:grid;grid-template-columns:repeat(3,1fr);text-align:center;padding:23px 4px;margin-top:25px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.profile-stats>view{border-right:1px solid var(--line)}.profile-stats>view:last-child{border:0}.local-card{padding:19px 0;margin-top:12px}.local-title{display:block;font-size:12px;font-weight:550;margin-bottom:4px}.local-card .helper{font-size:9px}.profile-quote{text-align:center;position:relative;margin:35px 0 30px;font-size:15px;color:#6f8065;line-height:2.2;letter-spacing:1px}.quote-mark{font-family:Georgia,serif;font-size:54px;color:#ccd7bf;display:block;line-height:.8;margin-bottom:5px}.quote-line{width:22px;height:1px;background:#b5c4a5;margin:19px auto 13px}.quote-en{font-size:8px;letter-spacing:2px;color:#a2ad98}</style>
